"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[306],{1661(t,e,n){n.r(e),n.d(e,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"part4-ml-foundations/introduction-pytorch","title":"PyTorch Foundations: Tensors, Autograd, Modules, and Training","description":"A practical journey through modern deep learning with PyTorch\u2014from first principles to real applications.","source":"@site/docs/part4-ml-foundations/01-introduction-pytorch.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/01-introduction-pytorch","permalink":"/tutorials/part4-ml-foundations/01-introduction-pytorch","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":1,"frontMatter":{"title":"PyTorch Foundations: Tensors, Autograd, Modules, and Training","slug":"/part4-ml-foundations/01-introduction-pytorch","description":"A practical journey through modern deep learning with PyTorch\u2014from first principles to real applications.","sidebar_label":"1. PyTorch foundations","pagination_label":"1. PyTorch foundations","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Part overview","permalink":"/tutorials/part4-ml-foundations/overview"},"next":{"title":"2. Machine learning as geometry","permalink":"/tutorials/part4-ml-foundations/02-ml-as-geometry"}}');var r=n(4848),a=n(8453),i=n(8172);const s=JSON.parse('{"sourcePath":"part4-ml-foundations/01-introduction-pytorch.html","route":"/part4-ml-foundations/01-introduction-pytorch","kind":"chapter","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"PyTorch Foundations: Tensors, Autograd, Modules, and Training","title":"PyTorch Foundations: Tensors, Autograd, Modules, and Training","description":"A practical journey through modern deep learning with PyTorch\u2014from first principles to real applications.","readingMinutes":5,"bodyClass":"","normalizeMath":false,"toc":[{"id":"start-from-basics","label":"We start from the very beginning"},{"id":"why-pytorch","label":"Why PyTorch"},{"id":"practical-apps","label":"Practical applications"},{"id":"tensor-model","label":"The four objects behind every PyTorch example"},{"id":"tensors","label":"Tensors: arrays with shape, dtype, and device"},{"id":"autograd","label":"Autograd: gradients from a recorded computation"},{"id":"modules","label":"Modules and parameters: a model is a callable object"},{"id":"first-loop","label":"The smallest complete training loop"},{"id":"debug-contract","label":"The first debugging contract: inspect shape, dtype, device, and range"},{"id":"how-to-use","label":"How we\u2019ll work"}],"html":"<div class=\\"wrap\\">\\n\\t\\t\\t<article class=\\"card\\">\\n\\t\\t\\t\\t<div class=\\"card__topbar\\" aria-hidden=\\"true\\"></div>\\n\\n\\t\\t\\t\\t<header>\\n\\t\\t\\t\\t\\t<div class=\\"kicker\\">Part IV \u2022 Machine Learning Foundations</div>\\n\\t\\t\\t\\t\\t\\n\\t\\t\\t\\t\\t<p class=\\"subtitle\\">\\n\\t\\t\\t\\t\\t\\tA practical journey through modern deep learning with PyTorch\u2014from first principles to\\n\\t\\t\\t\\t\\t\\treal applications.\\n\\t\\t\\t\\t\\t</p>\\n\\t\\t\\t\\t</header>\\n\\n\\t\\t\\t\\t<main>\\n\\t\\t\\t\\t\\t<p>\\n\\t\\t\\t\\t\\t\\tDeep learning has transformed how we work with data, from recognizing images and\\n\\t\\t\\t\\t\\t\\tunderstanding language to powering recommendation engines and game-playing agents. This\\n\\t\\t\\t\\t\\t\\tbook is a practical journey through modern deep learning with PyTorch, designed to take\\n\\t\\t\\t\\t\\t\\tyou from beginner to advanced without requiring a heavy math background (though pointers\\n\\t\\t\\t\\t\\t\\tto deeper theory are provided if you want them).\\n\\t\\t\\t\\t\\t</p>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"start-from-basics\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"start-from-basics\\">We start from the very beginning</h2>\\n\\t\\t\\t\\t\\t\\t<p>\\n\\t\\t\\t\\t\\t\\t\\tWe start from the very beginning: linear regression and the idea of a neuron as a\\n\\t\\t\\t\\t\\t\\t\\tsimple nonlinear transformation of a linear model. From there, we build up to deep\\n\\t\\t\\t\\t\\t\\t\\tneural networks, then explore specialized architectures:\\n\\t\\t\\t\\t\\t\\t</p>\\n\\t\\t\\t\\t\\t\\t<ul>\\n\\t\\t\\t\\t\\t\\t\\t<li><strong>Convolutional Neural Networks (CNNs)</strong> for images and signals</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Recurrent Neural Networks (RNNs)</strong> and LSTMs for sequences and time\\n\\t\\t\\t\\t\\t\\t\\t\\tseries\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Best practices</strong> for time series forecasting, including what commonly\\n\\t\\t\\t\\t\\t\\t\\t\\tgoes wrong in stock prediction tutorials\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t</ul>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"why-pytorch\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"why-pytorch\\">Why PyTorch</h2>\\n\\t\\t\\t\\t\\t\\t<p>\\n\\t\\t\\t\\t\\t\\t\\tAlong the way, you\u2019ll see how PyTorch\u2019s automatic differentiation and rich set of\\n\\t\\t\\t\\t\\t\\t\\tprebuilt layers let you focus on ideas and experiments instead of manually deriving and\\n\\t\\t\\t\\t\\t\\t\\tcoding gradients. PyTorch became popular partly because its eager, Python-first execution\\n\\t\\t\\t\\t\\t\\t\\tmodel was easier to inspect than the static-graph-first workflows used by Theano and\\n\\t\\t\\t\\t\\t\\t\\tearly TensorFlow. Modern TensorFlow also supports eager execution; both frameworks remain\\n\\t\\t\\t\\t\\t\\t\\tcapable, while this book uses PyTorch for one consistent implementation path.\\n\\t\\t\\t\\t\\t\\t</p>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"practical-apps\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"practical-apps\\">Practical applications</h2>\\n\\t\\t\\t\\t\\t\\t<p>The second half of the book focuses on applications that matter in practice:</p>\\n\\t\\t\\t\\t\\t\\t<ul>\\n\\t\\t\\t\\t\\t\\t\\t<li><strong>Natural Language Processing (NLP)</strong> and text classification</li>\\n\\t\\t\\t\\t\\t\\t\\t<li><strong>Embeddings</strong> for words and other categorical data</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Recommender systems</strong> as used by companies like Amazon, Facebook, and\\n\\t\\t\\t\\t\\t\\t\\t\\tGoogle\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Transfer learning</strong> with pretrained models, allowing you to leverage\\n\\t\\t\\t\\t\\t\\t\\t\\tmassive datasets like ImageNet\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Generative Adversarial Networks (GANs)</strong> for realistic image generation\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>\\n\\t\\t\\t\\t\\t\\t\\t\\t<strong>Reinforcement Learning (RL)</strong> for sequential decision-making and\\n\\t\\t\\t\\t\\t\\t\\t\\tcontrol\\n\\t\\t\\t\\t\\t\\t\\t</li>\\n\\t\\t\\t\\t\\t\\t</ul>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"tensor-model\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"tensor-model\\">The four objects behind every PyTorch example</h2>\\n\\t\\t\\t\\t\\t\\t<p>\\n\\t\\t\\t\\t\\t\\t\\tLater chapters introduce many architectures, but the training machinery\\n\\t\\t\\t\\t\\t\\t\\tchanges very little. Hold these four objects in your head:\\n\\t\\t\\t\\t\\t\\t</p>\\n\\n\\t\\t\\t\\t\\t\\t<table>\\n\\t\\t\\t\\t\\t\\t\\t<thead>\\n\\t\\t\\t\\t\\t\\t\\t\\t<tr><th>Object</th><th>Job</th><th>Typical PyTorch form</th></tr>\\n\\t\\t\\t\\t\\t\\t\\t</thead>\\n\\t\\t\\t\\t\\t\\t\\t<tbody>\\n\\t\\t\\t\\t\\t\\t\\t\\t<tr><td>Tensor</td><td>Stores numeric inputs, targets, parameters, and intermediate values.</td><td><code>torch.Tensor</code></td></tr>\\n\\t\\t\\t\\t\\t\\t\\t\\t<tr><td>Model</td><td>Maps an input tensor to an output tensor using learnable parameters.</td><td><code>nn.Module</code></td></tr>\\n\\t\\t\\t\\t\\t\\t\\t\\t<tr><td>Loss</td><td>Measures how wrong the model output is for the target.</td><td><code>nn.MSELoss</code>, <code>nn.CrossEntropyLoss</code></td></tr>\\n\\t\\t\\t\\t\\t\\t\\t\\t<tr><td>Optimizer</td><td>Updates parameters using their gradients.</td><td><code>torch.optim.SGD</code>, <code>AdamW</code></td></tr>\\n\\t\\t\\t\\t\\t\\t\\t</tbody>\\n\\t\\t\\t\\t\\t\\t</table>\\n\\n\\t\\t\\t\\t\\t\\t<div class=\\"figure-card\\">\\n\\t\\t\\t\\t\\t\\t\\t<h3 id=\\"visual-the-reusable-training-loop\\">Visual: the reusable training loop</h3>\\n\\t\\t\\t\\t\\t\\t\\t<svg class=\\"viz\\" viewBox=\\"0 0 980 260\\" role=\\"img\\" aria-label=\\"Tensor, model, loss, gradient, and optimizer training loop\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t<defs>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t<marker id=\\"pytorch-arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accentFill\\"></path>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t</marker>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t<marker id=\\"pytorch-arrow-purple\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accent2Fill\\"></path>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t</marker>\\n\\t\\t\\t\\t\\t\\t\\t\\t</defs>\\n\\t\\t\\t\\t\\t\\t\\t\\t<rect x=\\"24\\" y=\\"74\\" width=\\"150\\" height=\\"90\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"99\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">Input x</text>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"99\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">tensor</text>\\n\\n\\t\\t\\t\\t\\t\\t\\t\\t<rect x=\\"230\\" y=\\"74\\" width=\\"180\\" height=\\"90\\" rx=\\"14\\" class=\\"box\\"></rect>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"320\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">Model</text>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"320\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">prediction = f(x)</text>\\n\\n\\t\\t\\t\\t\\t\\t\\t\\t<rect x=\\"466\\" y=\\"74\\" width=\\"180\\" height=\\"90\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"556\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">Loss</text>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"556\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">compare to y</text>\\n\\n\\t\\t\\t\\t\\t\\t\\t\\t<rect x=\\"702\\" y=\\"74\\" width=\\"244\\" height=\\"90\\" rx=\\"14\\" class=\\"box\\"></rect>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"824\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">Optimizer</text>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"824\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">update parameters</text>\\n\\n\\t\\t\\t\\t\\t\\t\\t\\t<line x1=\\"174\\" y1=\\"119\\" x2=\\"230\\" y2=\\"119\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#pytorch-arrow)\\"></line>\\n\\t\\t\\t\\t\\t\\t\\t\\t<line x1=\\"410\\" y1=\\"119\\" x2=\\"466\\" y2=\\"119\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#pytorch-arrow)\\"></line>\\n\\t\\t\\t\\t\\t\\t\\t\\t<line x1=\\"646\\" y1=\\"119\\" x2=\\"702\\" y2=\\"119\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#pytorch-arrow-purple)\\"></line>\\n\\t\\t\\t\\t\\t\\t\\t\\t<path d=\\"M824 164 C804 224 392 230 320 164\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#pytorch-arrow-purple)\\"></path>\\n\\t\\t\\t\\t\\t\\t\\t\\t<text x=\\"560\\" y=\\"222\\" text-anchor=\\"middle\\" class=\\"muted\\">backward computes gradients; step changes parameters</text>\\n\\t\\t\\t\\t\\t\\t\\t</svg>\\n\\t\\t\\t\\t\\t\\t</div>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"tensors\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"tensors\\">Tensors: arrays with shape, dtype, and device</h2>\\n\\n\\t\\t\\t\\t\\t\\t<p>A tensor is a multidimensional numeric array. A scalar\\n\\t\\t\\t\\t\\t\\thas no axes, a vector has one, a matrix has two, and a batch\\n\\t\\t\\t\\t\\t\\tof color images often has four:\\n\\t\\t\\t\\t\\t\\t<code>[batch, channels, height, width]</code>.</p>\\n\\n<pre><code class=\\"language-python\\">import torch\\n\\nscalar = torch.tensor(3.0)                       # shape: []\\nvector = torch.tensor([1.0, 2.0, 3.0])          # shape: [3]\\nmatrix = torch.tensor([[1.0, 2.0], [3.0, 4.0]]) # shape: [2, 2]\\n\\nprint(matrix.shape)  # torch.Size([2, 2])\\nprint(matrix.dtype)  # usually torch.float32 here\\nprint(matrix.device) # cpu, unless moved to an accelerator</code></pre>\\n\\n\\t\\t\\t\\t\\t\\t<p>Shape describes axis lengths. <strong>Dtype</strong>\\n\\t\\t\\t\\t\\t\\tdescribes numeric representation, such as\\n\\t\\t\\t\\t\\t\\t<code>float32</code> or <code>int64</code>.\\n\\t\\t\\t\\t\\t\\t<strong>Device</strong> says where the storage and operation\\n\\t\\t\\t\\t\\t\\tlive, such as CPU, CUDA GPU, or Apple MPS. Tensors used in\\n\\t\\t\\t\\t\\t\\tone operation must have compatible shapes, dtypes, and\\n\\t\\t\\t\\t\\t\\tdevices.</p>\\n\\n<pre><code class=\\"language-python\\">device = (\\n    \\"cuda\\" if torch.cuda.is_available()\\n    else \\"mps\\" if torch.backends.mps.is_available()\\n    else \\"cpu\\"\\n)\\n\\nx = torch.randn(32, 10, device=device)  # 32 examples, 10 features each</code></pre>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"autograd\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"autograd\\">Autograd: gradients from a recorded computation</h2>\\n\\n\\t\\t\\t\\t\\t\\t<p>Training asks: \u201cHow should each parameter change to\\n\\t\\t\\t\\t\\t\\treduce the loss?\u201d PyTorch records operations involving\\n\\t\\t\\t\\t\\t\\ttensors that require gradients. Calling\\n\\t\\t\\t\\t\\t\\t<code>backward()</code> applies the chain rule backward\\n\\t\\t\\t\\t\\t\\tthrough that computation graph.</p>\\n\\n<pre><code class=\\"language-python\\">w = torch.tensor(2.0, requires_grad=True)\\nx = torch.tensor(3.0)\\ny = w * x ** 2\\n\\ny.backward()\\nprint(w.grad)  # 9.0 because dy/dw = x^2</code></pre>\\n\\n\\t\\t\\t\\t\\t\\t<p>The graph is a record of operations for this forward\\n\\t\\t\\t\\t\\t\\tpass, not a drawing you have to create manually. A new\\n\\t\\t\\t\\t\\t\\tgraph is normally built on the next pass. Gradients\\n\\t\\t\\t\\t\\t\\taccumulate in <code>.grad</code>, which is why training\\n\\t\\t\\t\\t\\t\\tloops clear them before the next backward pass.</p>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"modules\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"modules\\">Modules and parameters: a model is a callable object</h2>\\n\\n\\t\\t\\t\\t\\t\\t<p><code>nn.Module</code> is the base class for trainable\\n\\t\\t\\t\\t\\t\\tPyTorch components. It registers nested modules and\\n\\t\\t\\t\\t\\t\\tparameters so the optimizer, device movement, saving, and\\n\\t\\t\\t\\t\\t\\ttraining/evaluation modes work recursively.</p>\\n\\n<pre><code class=\\"language-python\\">from torch import nn\\n\\nclass LinearRegressor(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n        self.linear = nn.Linear(in_features=1, out_features=1)\\n\\n    def forward(self, x: torch.Tensor) -&gt; torch.Tensor:\\n        return self.linear(x)\\n\\nmodel = LinearRegressor()\\nprediction = model(torch.tensor([[2.0]]))  # call model(...), not forward(...)</code></pre>\\n\\n\\t\\t\\t\\t\\t\\t<p>The learnable weight and bias are\\n\\t\\t\\t\\t\\t\\t<code>nn.Parameter</code> objects. They are tensors with\\n\\t\\t\\t\\t\\t\\tgradient tracking that were registered because\\n\\t\\t\\t\\t\\t\\t<code>self.linear</code> is a child module.</p>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"first-loop\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"first-loop\\">The smallest complete training loop</h2>\\n\\n\\t\\t\\t\\t\\t\\t<p>This example learns the relationship\\n\\t\\t\\t\\t\\t\\t<code>y = 2x + 1</code>. Later chapters change the data,\\n\\t\\t\\t\\t\\t\\tmodel, and loss, but keep this loop structure.</p>\\n\\n<pre><code class=\\"language-python\\">import torch\\nfrom torch import nn\\n\\nx = torch.tensor([[0.0], [1.0], [2.0], [3.0]])\\ny = torch.tensor([[1.0], [3.0], [5.0], [7.0]])\\n\\nmodel = nn.Linear(1, 1)\\nloss_fn = nn.MSELoss()\\noptimizer = torch.optim.SGD(model.parameters(), lr=0.05)\\n\\nfor step in range(500):\\n    model.train()\\n\\n    prediction = model(x)           # 1) forward pass\\n    loss = loss_fn(prediction, y)   # 2) measure error\\n\\n    optimizer.zero_grad()           # 3) clear old gradients\\n    loss.backward()                 # 4) compute new gradients\\n    optimizer.step()                # 5) update weight and bias\\n\\nmodel.eval()\\nwith torch.no_grad():\\n    print(model(torch.tensor([[4.0]])))  # close to 9</code></pre>\\n\\n\\t\\t\\t\\t\\t\\t<p><code>model.train()</code> and\\n\\t\\t\\t\\t\\t\\t<code>model.eval()</code> control layers whose behavior\\n\\t\\t\\t\\t\\t\\tdiffers by mode, such as dropout and batch normalization.\\n\\t\\t\\t\\t\\t\\t<code>torch.no_grad()</code> disables gradient recording\\n\\t\\t\\t\\t\\t\\tfor this evaluation block, reducing memory and work. It\\n\\t\\t\\t\\t\\t\\tdoes not replace <code>eval()</code>; the two controls solve\\n\\t\\t\\t\\t\\t\\tdifferent problems.</p>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"debug-contract\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"debug-contract\\">The first debugging contract: inspect shape, dtype, device, and range</h2>\\n\\n\\t\\t\\t\\t\\t\\t<p>Before changing an architecture, print the boundary\\n\\t\\t\\t\\t\\t\\tfacts. Many apparent \u201cmodel problems\u201d are tensor contract\\n\\t\\t\\t\\t\\t\\tproblems:</p>\\n\\n<pre><code class=\\"language-python\\">print(\\"x:\\", x.shape, x.dtype, x.device)\\nprint(\\"y:\\", y.shape, y.dtype, y.device)\\nprint(\\"prediction:\\", prediction.shape)\\nprint(\\"finite:\\", torch.isfinite(loss).item())</code></pre>\\n\\n\\t\\t\\t\\t\\t\\t<ul>\\n\\t\\t\\t\\t\\t\\t\\t<li>Regression predictions and targets usually need matching floating-point shapes.</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>Class indices for <code>CrossEntropyLoss</code> are normally <code>torch.long</code>.</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>Do not mix CPU inputs with a GPU model.</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>Do not silently broadcast incompatible target and prediction shapes.</li>\\n\\t\\t\\t\\t\\t\\t\\t<li>Check for NaN or infinity before tuning hyperparameters.</li>\\n\\t\\t\\t\\t\\t\\t</ul>\\n\\t\\t\\t\\t\\t</section>\\n\\n\\t\\t\\t\\t\\t<section class=\\"section\\" aria-labelledby=\\"how-to-use\\">\\n\\t\\t\\t\\t\\t\\t<h2 id=\\"how-to-use\\">How we\u2019ll work</h2>\\n\\t\\t\\t\\t\\t\\t<p>\\n\\t\\t\\t\\t\\t\\t\\tThroughout, we will rely on PyTorch and GPU-backed environments (such as Google Colab),\\n\\t\\t\\t\\t\\t\\t\\tso you can train powerful models even if you don\u2019t have specialized hardware. The goal\\n\\t\\t\\t\\t\\t\\t\\tis not just to show you which buttons to press, but to help you understand why the\\n\\t\\t\\t\\t\\t\\t\\tarchitectures work, where they fail, and how to adapt them to your own projects.\\n\\t\\t\\t\\t\\t\\t</p>\\n\\n\\t\\t\\t\\t\\t\\t<div class=\\"callout\\" role=\\"note\\">\\n\\t\\t\\t\\t\\t\\t\\t<strong>Progression:</strong> The next chapter turns\\n\\t\\t\\t\\t\\t\\t\\ttensors into geometry: rows become points, model\\n\\t\\t\\t\\t\\t\\t\\tparameters define lines or separating boundaries, and\\n\\t\\t\\t\\t\\t\\t\\tloss measures how poorly that geometry fits the data.\\n\\t\\t\\t\\t\\t\\t\\tThe regression chapter then implements the same loop\\n\\t\\t\\t\\t\\t\\t\\tabove one line at a time.\\n\\t\\t\\t\\t\\t\\t</div>\\n\\t\\t\\t\\t\\t</section>\\n\\t\\t\\t\\t</main>\\n\\n\\t\\t\\t\\t<div class=\\"footer\\">Deep Learning with PyTorch \u2022 Chapter 1</div>\\n\\t\\t\\t</article>\\n\\t\\t</div>"}'),l={title:"PyTorch Foundations: Tensors, Autograd, Modules, and Training",slug:"/part4-ml-foundations/01-introduction-pytorch",description:"A practical journey through modern deep learning with PyTorch\u2014from first principles to real applications.",sidebar_label:"1. PyTorch foundations",pagination_label:"1. PyTorch foundations",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},h=[];function p(t){return(0,r.jsx)(i.A,{content:s})}function u(t={}){const{wrapper:e}={...(0,a.R)(),...t.components};return e?(0,r.jsx)(e,{...t,children:(0,r.jsx)(p,{...t})}):p()}}}]);